// Hand-written (not generated by scripts/stitch-to-jsx.mjs). Content lives in src/data/caseStudies.js.
import { Link, Navigate, useParams } from 'react-router-dom'
import { caseStudies, categories } from '../data/caseStudies.js'
import { products } from '../data/pages.js'

const card = 'rounded-2xl bg-surface-container-lowest/85 backdrop-blur-xl border border-white/90 shadow-[0_16px_36px_-6px_rgba(31,26,23,0.04)]'
const tag = 'px-3 py-1 rounded-[6px] bg-primary-container/15 text-primary text-label-sm font-label-sm uppercase tracking-wider font-semibold'

function Block({ icon, title, children }) {
  return (
    <div className={`${card} p-8`}>
      <h2 className="text-headline-sm font-headline-sm text-on-surface font-semibold mb-3 flex items-center gap-2">
        <span className="material-symbols-outlined text-primary text-[22px]" aria-hidden="true">{icon}</span>
        {title}
      </h2>
      {children}
    </div>
  )
}

export default function CaseStudyDetail() {
  const { slug } = useParams()
  const cs = caseStudies.find((c) => c.slug === slug)
  if (!cs) return <Navigate to="/case-studies" replace />
  const used = cs.products.map((s) => products.find((p) => p.slug === s))
  const more = caseStudies.filter((c) => c !== cs && c.category === cs.category).concat(caseStudies.filter((c) => c !== cs && c.category !== cs.category)).slice(0, 3)

  return (
    <div className="bg-background text-on-background antialiased">
      <title>{`${cs.title} — Horizon Case Study`}</title>
      <main className="max-w-7xl mx-auto px-6 md:px-12 pt-12 pb-8 space-y-10">
        <nav className="text-label-md text-on-surface-variant flex items-center gap-2" aria-label="Breadcrumb">
          <Link to="/case-studies" className="hover:text-primary transition-colors">Case Studies</Link>
          <span aria-hidden="true">/</span>
          <span className="text-on-surface">{cs.industry}</span>
        </nav>

        <section className={`${card} overflow-hidden grid grid-cols-1 ${cs.image ? 'lg:grid-cols-2' : ''}`}>
          <div className="p-8 md:p-12">
            <div className="flex flex-wrap items-center gap-3 mb-6">
              <span className={tag}>{categories[cs.category]}</span>
              <span className="text-label-md text-on-surface-variant">{cs.industry}</span>
            </div>
            <h1 className="text-headline-lg md:text-display-lg font-display-lg text-on-surface font-bold tracking-tight mb-6">{cs.title}</h1>
            <p className="text-body-lg text-on-surface-variant leading-relaxed">{cs.summary}</p>
          </div>
          {cs.image && <img src={cs.image} alt="" className="w-full h-full min-h-[280px] object-cover" />}
        </section>

        <div className="grid grid-cols-1 lg:grid-cols-12 gap-8 items-start">
          <div className="lg:col-span-8 space-y-6">
            <Block icon="warning" title="The challenge">
              <p className="text-body-md text-on-surface-variant leading-relaxed">{cs.challenge}</p>
            </Block>
            <Block icon="hub" title="Our approach">
              <p className="text-body-md text-on-surface-variant leading-relaxed">{cs.approach}</p>
            </Block>
            <Block icon="task_alt" title="What we delivered">
              <ul className="space-y-3">
                {cs.delivered.map((d) => (
                  <li key={d} className="flex items-start gap-3 text-body-md text-on-surface-variant">
                    <span className="material-symbols-outlined text-primary text-[20px] mt-0.5" aria-hidden="true">check_circle</span>
                    {d}
                  </li>
                ))}
              </ul>
            </Block>
            <Block icon="flag" title="The outcome">
              <p className="text-body-md text-on-surface-variant leading-relaxed">{cs.outcome}</p>
            </Block>
          </div>

          <aside className="lg:col-span-4 space-y-6 lg:sticky lg:top-28">
            <div className={`${card} p-6 space-y-5`}>
              <div>
                <div className="text-label-sm uppercase tracking-wider text-on-surface-variant mb-1">Client</div>
                <div className="text-body-md text-on-surface font-semibold">{cs.client}</div>
              </div>
              <div>
                <div className="text-label-sm uppercase tracking-wider text-on-surface-variant mb-1">Industry</div>
                <div className="text-body-md text-on-surface font-semibold">{cs.industry}</div>
              </div>
              <div>
                <div className="text-label-sm uppercase tracking-wider text-on-surface-variant mb-1">Engagement</div>
                <div className="text-body-md text-on-surface font-semibold">{categories[cs.category]}</div>
              </div>
              {used.length > 0 && (
                <div>
                  <div className="text-label-sm uppercase tracking-wider text-on-surface-variant mb-2">Products used</div>
                  <ul className="space-y-2">
                    {used.map((p) => (
                      <li key={p.slug}>
                        <Link to={p.path} className="inline-flex items-center gap-1.5 text-label-lg font-semibold text-primary hover:text-on-primary-container transition-colors">
                          {p.name}
                          <span className="material-symbols-outlined text-[16px]" aria-hidden="true">arrow_forward</span>
                        </Link>
                      </li>
                    ))}
                  </ul>
                </div>
              )}
            </div>
            <div className="rounded-2xl bg-gradient-to-br from-[#FF8A65] to-[#FF6B4A] p-6 text-white shadow-lg">
              <h2 className="text-headline-sm font-bold mb-2">Facing a similar problem?</h2>
              <p className="text-body-md text-white/90 mb-5">Tell us how your team works today and we will scope a fixed-price plan.</p>
              <Link to="/contact" className="inline-flex px-5 py-3 rounded-[10px] bg-white text-primary text-label-lg font-bold shadow-md hover:bg-surface-container-lowest transition-colors">
                Book a scoping call
              </Link>
            </div>
          </aside>
        </div>

        <section className="pt-6">
          <h2 className="text-headline-md font-headline-md text-on-surface font-bold mb-6">More case studies</h2>
          <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
            {more.map((c) => (
              <Link key={c.slug} to={`/case-studies/${c.slug}`} className={`${card} p-6 flex flex-col gap-3 hover:-translate-y-1 transition-transform duration-200`}>
                <span className="text-label-sm text-on-surface-variant">{c.industry}</span>
                <span className="text-headline-sm font-headline-sm text-on-surface font-bold">{c.title}</span>
                <span className="mt-auto inline-flex items-center gap-1.5 text-label-lg font-semibold text-primary">
                  Read case study
                  <span className="material-symbols-outlined text-[16px]" aria-hidden="true">arrow_forward</span>
                </span>
              </Link>
            ))}
          </div>
        </section>
      </main>
    </div>
  )
}
